        ) | ForEach-Object { Get-TestResultFile -Path (Join-Path $FixturesPath $_) }

        $flaky = Find-FlakyTests -Results $files
    }

    It 'Finds exactly two flaky tests' {
        $flaky.Count | Should -Be 2
    }

